# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_merge_a import M,A
IM=M+[['拉丁 in- + mergere → immergere，分词 immersus','放入、浸在里面'],['英语 immerse','浸入液体 → 把注意力放进一件事']]
SU=M+[['拉丁 sub- + mergere → submergere，分词 submersus','使沉到下面、淹没']]
DE=M+[['拉丁 dē- + mergere → dēmergere，分词 dēmersus','向下沉、使没入']]
WB=[
E('immerse','英 /ɪˈmɜːs/；美 /ɪˈmɜːrs/','浸入；使沉浸、专心投入','把东西整个放进水里，再把这个画面搬到注意力上：整个人投入进去。','拉丁 in-“进入” + mergere“浸入”→ immergere；英语借用其分词 immersus 的词干。',IM,'immerse a cloth in water 是把布浸进水里；immerse yourself in a book 是完全投入阅读。抽象义不要求与外界隔绝，只突出注意力深深进入某件事。','immerse something in；immerse yourself in a subject。','dip 往往只是蘸一下或短暂浸入；immerse 更突出浸没、充分接触。emerge 的方向是出来。',('Immerse the cloth in clean water.','把布浸入清水中。'),('She immersed herself in the history of the city.','她全心投入了这座城市历史的研究。'),sources=['https://www.etymonline.com/word/immerse']),
E('immersed','英 /ɪˈmɜːst/；美 /ɪˈmɜːrst/','浸在其中的；全神贯注的','人或物已经进入里面，周围是水，也可以是一本书或一项研究。','immerse + -d；词尾合起来读 /st/，不额外加一个音节。',A(IM,'英语 immersed','已经浸入；处于沉浸的状态'),'be immersed in work 常说专注工作；be immersed in water 是物理上的浸水。看 in 后面的对象，就能判断用的是水的画面还是注意力的画面。','deeply immersed in；fully immersed；immersed in a book。','immersed 描述人或物的状态；immersive 描述能把人带进去的体验。',('He was so immersed in the book that he missed his stop.','他看书看得太投入，坐过了站。'),('The lower half of the rock remained immersed in water.','这块石头的下半部分一直浸在水里。')),
E('immersion','英 /ɪˈmɜːʃən/；美 /ɪˈmɜːrʒən/','浸入；沉浸；浸入式学习','不是远远看一点，而是让自己充分处在那个环境里。','经晚期拉丁 immersio，来自 immergere；现代可联系 immerse 和名词词尾 -ion，历史上不是只能由英语动词临时拼出。',IM[:2]+[['晚期拉丁 immersio → 英语 immersion','浸入这一过程 → 深入某环境的体验']],'language immersion 是大量用目标语言生活或学习，让语言成为环境的一部分。读懂这个词，不必想成“一秒钟都不能说母语”；核心是接触的深度和持续性。','immersion in water；language immersion；total immersion。','immersion 朝里；emersion 朝外。普通学习课程也可能有 immersion，不只虚拟现实才叫沉浸。',('The programme offers a month of immersion in Spanish.','这个项目提供一个月的西班牙语浸入式学习。'),('The coating was tested after repeated immersion in water.','涂层经过反复浸水后接受了测试。'),sources=['https://www.etymonline.com/word/immersion']),
E('immersive','英 /ɪˈmɜːsɪv/；美 /ɪˈmɜːrsɪv/','让人沉浸其中的；沉浸式的','体验把你的注意力包围起来，让你像进入了那个世界。','immerse 去词尾 e + -ive，形成形容词。',A(IM,'英语 immersive','能够使人投入、沉浸的'),'an immersive exhibition 可以通过声音、空间、故事等让人投入。它不自动表示必须戴头显，也不等于设备多；一本抓人的小说也能提供 immersive experience。','an immersive experience；immersive storytelling；an immersive exhibition。','immersive 修饰体验的吸引力或包围感；immersed 描述参与者已经投入的状态。',('Sound and lighting made the exhibition more immersive.','声音和灯光让展览更有沉浸感。'),('The novel creates an immersive world with very little description.','这本小说用不多的描写就营造了一个让人投入其中的世界。')),
E('immersible','英 /ɪˈmɜːsəbəl/；美 /ɪˈmɜːrsəbəl/','可浸入液体而不损坏的','东西不是一碰水就坏，而是设计上能够放到液体里面使用或清洗。','immers-，与拉丁 immersus、英语 immerse 相联 + -ible“能够……的”。',IM[:2]+[['英语 immersible','能够承受浸入的']],'an immersible device 通常指能够浸入而不损坏的设备。具体能浸多久、浸多深，仍由产品条件决定；单词本身没有给出无限制的承诺。','an immersible heater；an immersible component。','waterproof 范围较广，描述防水；immersible 明确突出可以浸入。别把它读成 immersive，后者谈沉浸体验。',('Only the marked part of the heater is immersible.','加热器只有标明的部分可以浸入液体。'),('The manual states that the container is fully immersible.','说明书写明这个容器可以完全浸入水中。'),sources=['https://www.merriam-webster.com/dictionary/immersible']),
E('reimmerse','英 /ˌriːɪˈmɜːs/；美 /ˌriːɪˈmɜːrs/','再次浸入；重新投入','拿出来之后再放进去，或分心之后重新进入那件事。','re-“再次” + immerse。',A(IM,'英语 reimmerse','再次浸入；重新沉浸'),'reimmerse the sample 是把样品再次浸入液体；reimmerse yourself in a story 是重新投入故事。两处 i 属于不同部分，re- 后面接完整 immerse。','reimmerse something in；reimmerse yourself in。','reemerge 是再次出来；reimmerse 是再次进去。字母差一点，方向相反。',('The researcher reimmersed the sample in the solution.','研究人员把样品重新浸入溶液中。'),('After the interruption, she tried to reimmerse herself in the story.','被打断后，她试着重新投入故事。')),
E('immerge','英 /ɪˈmɜːdʒ/；美 /ɪˈmɜːrdʒ/','浸入；沉入〔少见〕','方向是往里面沉，尽管它听起来可能与 emerge 一样。','借自拉丁 immergere，保留 merg-；immerse 则取分词 immersus 的 mers- 形式。',IM[:2]+[['英语 immerge','浸入、使沉入；较少见的动词形式']],'immerge 和 immerse 同属“向内浸入”支线。日常表达通常选 immerse 或 submerge；看到较旧或专门文字里的 immerge，不能因读音就读成 emerge“冒出来”。','immerge in water；immerge an object。','immerge 的 im- 来自 in-，往里；emerge 的 e- 来自 ex-，往外。两词在常见读法中同音。',('In the demonstration, the operator immerged the specimen in water.','演示中，操作人员把标本浸入水里。'),('The older instructions tell the reader to immerge the cloth completely.','旧说明要求读者把布完全浸入液体。'),sources=['https://www.etymonline.com/word/immerge','https://www.merriam-webster.com/dictionary/immerge']),
E('immergence','英 /ɪˈmɜːdʒəns/；美 /ɪˈmɜːrdʒəns/','浸入、沉入的过程〔少见〕','把东西从外面放到里面去这件事，作为一个过程来谈。','immerge 去词尾 e + -ence，形成名词。',IM[:2]+[['英语 immerge → immergence','浸入 → 浸入的动作或过程']],'这个词较少见，普通“浸泡、沉浸”常用 immersion。理解 immergence 的价值在于认出方向，不必为了显得高级而用它替代自然的常用词。','immergence in liquid；the process of immergence。','emergence 是出现；immergence 是浸入。读音可能相同，必须看拼写和上下文。',('The old account describes the object’s gradual immergence in the liquid.','这段旧记述描写了物体逐渐浸入液体的过程。'),('Here, “immergence” refers to going under the water, not coming out of it.','这里的 immergence 指进入水下，而不是从水里出来。'),sources=['https://www.merriam-webster.com/dictionary/immergence']),
E('submersible','英 /səbˈmɜːsəbəl/；美 /səbˈmɜːrsəbəl/','可潜入水下的；潜水器','先是“能够在水下工作”，再用这个特点直接称呼一台下水作业的设备。','submers-，与拉丁 submersus“淹没的”相联 + -ible“能够……的”。',SU+[['英语 submersible','可浸没、可潜水的 → 潜水器']],'a submersible pump 是潜水泵；a research submersible 是科研潜水器。名词可以指载人或无人设备，不能一看到这个词就认定里面一定坐着人。','a submersible pump；a research submersible；an unmanned submersible。','submarine 可指潜艇，也有水下的形容词义；submersible 常见于科研和作业设备，不能简单等同军用潜艇。',('The team used a submersible to inspect the wreck.','团队用一台潜水器检查沉船。'),('A submersible pump removed water from the flooded room.','一台潜水泵把积水房间里的水抽走了。'),sources=['https://www.merriam-webster.com/dictionary/submersible']),
E('submersion','英 /səbˈmɜːʃən/；美 /səbˈmɜːrʒən/','淹没；浸没','水面高过物体，让它处在水下。','来自拉丁 submersio／summersio，接 submergere 的分词词干；现代可联系 submerge，但不必编成英语先造动词再造名词。',SU+[['拉丁 submersio／summersio → 英语 submersion','使沉入、浸没这一过程或状态']],'submersion 常关注物体在液面之下。它可以指设备、土地等，不必涉及人；也可以出现在专门领域，具体对象决定含义。','complete submersion；submersion in water；prolonged submersion。','immersion 和 submersion 有重合；submersion 更突出被液面盖住，immersion 还常用于投入学习等抽象环境。',('The camera was tested for brief submersion in water.','这台相机做了短时间浸水测试。'),('Repeated submersion damaged the wooden steps.','反复被水淹没损坏了木台阶。'),sources=['https://www.merriam-webster.com/dictionary/submersion','https://en.wiktionary.org/wiki/submersion']),
E('submergence','英 /səbˈmɜːdʒəns/；美 /səbˈmɜːrdʒəns/','沉入水下；被淹没；淹没状态','把“逐渐进入水面之下”或“持续在水下”作为一件事来描述。','submerge 去词尾 e + -ence。',SU+[['英语 submerge → submergence','沉入、淹没 → 这一过程或状态']],'the submergence of an island 可以说岛屿被水淹没；submergence time 可以说设备留在水下多久。它与 submersion 常能表达相近意思，不要硬造一条所有领域通用的界线。','the submergence of；submergence time；gradual submergence。','submergence 保留 /dʒ/；submersion 常有 /ʃ/ 或 /ʒ/，不要只看中文意思就忽略读音。',('The map shows the gradual submergence of the coastline.','这张地图显示了海岸逐渐被淹没的情况。'),('The sensor recorded the duration of each submergence.','传感器记录了每次浸没持续的时间。')),
E('submerse','英 /səbˈmɜːs/；美 /səbˈmɜːrs/','使浸没；使沉入水下〔较少见〕','把整个东西放到水面下，基本方向与 submerge 相同。','借自拉丁 submersus，submergere 的过去分词；不是把现代 submerge 的 g 任意换成 s。',SU+[['英语 submerse','借用分词词干，表示使浸没']],'submerse 是成立的英语动词，但普通表达更常见 submerge。读科学说明或旧文章遇到它，抓住“放到液面以下”即可，不必为两者虚构完全不同的动作。','submerse an object in；fully submerse。','submerge 保留 merg-；submerse 使用 mers-。两者相联，但拼写与发音有各自固定形式。',('The technician submersed the sealed container in water.','技术人员把密封容器浸入水中。'),('The instructions say to submerse the entire sample.','说明要求把整个样品浸没。'),sources=['https://www.merriam-webster.com/dictionary/submerse']),
E('demersal','英 /dɪˈmɜːsəl/；美 /dɪˈmɜːrsəl/','近底栖息的；沉到底部的〔水生生物〕','把视线从水面一直往下移，看到靠近底部生活或落在底部的生物、卵等。','拉丁 dēmergere“使下沉”→ dēmersus + -al；这里 de- 是向下。',DE+[['英语 demersal','沉下去的 → 与水底或近底生活相关的']],'demersal fish 是在海底或湖底附近生活、活动的鱼。这里的“底”不等于“很深”：浅水区域也有底部；demersal eggs 则突出卵沉在底部。','demersal fish；demersal species；demersal eggs。','pelagic 说开阔水体中的生活方式；demersal 说靠近底部，不是“深海鱼”的通用替代词。',('The survey focused on demersal fish near the coast.','这次调查重点研究近岸的底栖鱼类。'),('The species lays demersal eggs that remain near the bottom.','这个物种产下沉在底部附近的卵。'),sources=['https://www.merriam-webster.com/dictionary/demersal']),
E('demerse','英 /dəˈmɜːs/；美 /dɪˈmɜːrs/','使沉入；使浸没〔古旧〕','把东西往下按进液体里，而不是把合并的公司拆开。','接拉丁 dēmersus，dēmergere 的分词；dē- 表向下，mers- 表浸没。',DE+[['英语 demerse','使沉入、浸没；古旧词']],'现代普通写作通常会选 immerse 或 submerge。demerse 的学习重点是识别旧文，并看懂 de- 在这里的方向；不必刻意塞进日常对话。','demerse in water〔古旧表达〕。','现代商业 demerge 表分拆，de- 表撤销；demerse 的历史 de- 表向下，不能只差一个字母就当同义词。',('In the old narrative, the wave demerses the small boat.','在那段旧叙述中，海浪将小船淹没。'),('The archaic instruction uses “demerse” where a modern writer would use “immerse”.','这条古旧说明用了 demerse，现代作者通常会用 immerse。'),sources=['https://www.collinsdictionary.com/dictionary/english/demerse','https://en.wiktionary.org/wiki/demerse']),
E('demersion','英 /dɪˈmɜːʃən/；美 /dɪˈmɜːrʒən/','浸没；沉入液体〔古旧〕','把“往下沉入液体”这件事说成一个名词。','拉丁 dēmersio，接 dēmergere 的分词词干 dēmers-；与 demerse 同族。',DE+[['拉丁 dēmersio → 英语 demersion','沉入、浸没这个过程']],'这个词已很少用于普通现代交流，意思与 immersion、submersion 相近。认识它，是为了阅读旧文字时能把“沉入”这个动作还原出来。','demersion in water〔古旧表达〕。','demerger 是企业分拆；demersion 是沉入液体。词形接近，路径却不同。',('The old report describes the demersion of the vessel during the storm.','这份旧报告描述了船只在风暴中沉没的情况。'),('The editor replaced “demersion” with the more familiar “immersion”.','编辑把 demersion 换成了读者更熟悉的 immersion。'),sources=['https://www.collinsdictionary.com/dictionary/english/demersion','https://en.wiktionary.org/wiki/demersion']),
]
